        private static Player CreatePlayer(string username, string email, string bio, Position preferredPosition, int age)
            => new()
            {
                Id = Guid.NewGuid(),
                Username = username,
                Email = email,
                Bio = bio,
                PreferredPosition = preferredPosition,
                Age = age,
                ProfilePicture = CreateAvatarSvg(username, preferredPosition)
            };

        private static byte[] CreateAvatarSvg(string username, Position preferredPosition)
        {
            var initials = GetInitials(username);

            var (primary, secondary, accent) = preferredPosition switch
            {
                Position.Goalkeeper => ("#0f766e", "#164e63", "#5eead4"),
                Position.Defender => ("#1d4ed8", "#1e3a8a", "#93c5fd"),
                Position.Midfielder => ("#6d28d9", "#312e81", "#c4b5fd"),
                Position.Forward => ("#be123c", "#7f1d1d", "#fda4af"),
                _ => ("#1f2937", "#111827", "#9ca3af")
            };

            var safeInitials = System.Net.WebUtility.HtmlEncode(initials);
            var svg = $"""
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128" role="img" aria-label="{safeInitials} avatar">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="{primary}" />
      <stop offset="100%" stop-color="{secondary}" />
    </linearGradient>
  </defs>
  <rect width="128" height="128" rx="24" fill="url(#bg)" />
  <circle cx="103" cy="26" r="12" fill="{accent}" opacity="0.85" />
  <text x="64" y="76" fill="#f8fafc" font-size="48" font-family="Segoe UI, sans-serif" font-weight="700" text-anchor="middle">{safeInitials}</text>
</svg>
""";

            return Encoding.UTF8.GetBytes(svg);
        }

        private static string GetInitials(string username)
        {
            var parts = username
                .Split(['_', '-', '.'], StringSplitOptions.RemoveEmptyEntries)
                .Where(part => !string.IsNullOrWhiteSpace(part))
                .Take(2)
                .ToArray();

            if (parts.Length == 0)
            {
                return "P";
            }

            return string.Concat(parts.Select(part => char.ToUpperInvariant(part[0])));
        }

        private static Party CreateParty(string description, string locations, DateTime firstDate, int maxMembers)
        {
            var creator = CreatePlayer(
                username: $"creator_{Guid.NewGuid().ToString("N")[..8]}",
                email: $"creator_{Guid.NewGuid().ToString("N")[..8]}@matchhub.com",
                bio: "Party organizer who prefers balanced teams.",
                preferredPosition: Position.Midfielder,
                age: 30);

            var party = new Party
            {
                Id = Guid.NewGuid(),
                PlayerCreatedId = creator.Id,
                // Keep deterministic and unique per party so Details routing can match by createdAt.
                DateCreated = firstDate.Date.AddDays(-14),
                MaxMembers = maxMembers,
                PartyDescription = description,
                PreferredLocations = locations,
                PlayerCreated = creator,
                Members =
                [
                    creator,
                    CreatePlayer($"member_{Guid.NewGuid().ToString("N")[..6]}", $"member_{Guid.NewGuid().ToString("N")[..6]}@matchhub.com", "Regular pickup player.", Position.Defender, 26),
                    CreatePlayer($"member_{Guid.NewGuid().ToString("N")[..6]}", $"member_{Guid.NewGuid().ToString("N")[..6]}@matchhub.com", "Weekend midfielder.", Position.Midfielder, 24),
                    CreatePlayer($"member_{Guid.NewGuid().ToString("N")[..6]}", $"member_{Guid.NewGuid().ToString("N")[..6]}@matchhub.com", "Fast counter-attacking forward.", Position.Forward, 22)
                ]
            };

            party.PreferredPlayingDates =
            [
                new PreferredPlayingDate
                {
                    Id = Guid.NewGuid(),
                    PartyId = party.Id,
                    Date = firstDate,
                    Party = party
                },
                new PreferredPlayingDate
                {
                    Id = Guid.NewGuid(),
                    PartyId = party.Id,
                    Date = firstDate.AddDays(1),
                    Party = party
                }
            ];

            return party;
        }

        private static PlayingField CreatePlayingField(
            string name,
            string description,
            double longitude,
            double latitude,
            string contactNumber,
            FieldStatus status,
            bool isOutdoor,
            SurfaceType surfaceType,
            int countOfPlayedMatches,
            string? fieldImage = null)
            => new()
            {
                Id = Guid.NewGuid(),
                Name = name,
                Description = description,
                Longitude = longitude,
                Latitude = latitude,
                Image = fieldImage !=null ? Convert.FromBase64String(fieldImage) : [],
                ContactNumber = contactNumber,
                Status = status,
                IsOutdoor = isOutdoor,
                SurfaceType = surfaceType,
                CountOfPlayedMatches = countOfPlayedMatches
            };

        private static MatchRecord CreateMatchRecord(
            DateTime heldAt,
            int goalsTeamA,
            int goalsTeamB,
            PlayingField field,
            List<Player> teamAPlayers,
            List<Player> teamBPlayers)
        {
            var match = new MatchRecord
            {
                Id = Guid.NewGuid(),
                WasMatchHeld = true,
                MatchHeld = heldAt,
                PlayingFieldId = field.Id,
                GoalsTeamA = goalsTeamA,
                GoalsTeamB = goalsTeamB,
                PlayingField = field
            };

            var matchPlayers = new List<MatchPlayer>();

            for (int i = 0; i < teamAPlayers.Count; i++)
            {
                var player = teamAPlayers[i];
                var entry = new MatchPlayer
                {
                    Id = Guid.NewGuid(),
                    PlayerId = player.Id,
                    Team = Team.A,
                    MatchRecordId = match.Id,
                    Goals = i < goalsTeamA ? 1 : 0,
                    Assists = i < goalsTeamA ? 1 : 0,
                    Player = player,
                    MatchRecord = match
                };

                if (i == 0)
                {
                    entry.PlayerRating = new PlayerRating
                    {
                        Id = Guid.NewGuid(),
                        MatchPlayerId = entry.Id,
                        PlayerGivingRatingId = player.Id,
                        PlayerReceivingRatingId = player.Id,
                        Rating = 8,
                        MatchPlayer = entry,
                        PlayerGivingRating = player,
                        PlayerReceivingRating = player
                    };
                }

                matchPlayers.Add(entry);
            }

            for (int i = 0; i < teamBPlayers.Count; i++)
            {
                var player = teamBPlayers[i];
                var entry = new MatchPlayer
                {
                    Id = Guid.NewGuid(),
                    PlayerId = player.Id,
                    Team = Team.B,
                    MatchRecordId = match.Id,
                    Goals = i < goalsTeamB ? 1 : 0,
                    Assists = i < goalsTeamB ? 1 : 0,
                    Player = player,
                    MatchRecord = match
                };

                matchPlayers.Add(entry);
            }

            match.MatchPlayers = matchPlayers;
            match.MatchVotes =
            [
                new MatchVote
                {
                    Id = Guid.NewGuid(),
                    MatchRecordId = match.Id,
                    PlayerId = teamAPlayers[0].Id,
                    VotedHeld = true,
                    MatchRecord = match,
                    Player = teamAPlayers[0]
                },
                new MatchVote
                {
                    Id = Guid.NewGuid(),
                    MatchRecordId = match.Id,
                    PlayerId = teamBPlayers[0].Id,
                    VotedHeld = true,
                    MatchRecord = match,
                    Player = teamBPlayers[0]
                }
            ];

            field.MatchRecords = [match];

            return match;
        }

    }
